22	namespace zvec::sqlengine {
23	
24	Status DocFilter::compute_filter() {
25	  if (invert_cond_) {
26	    InvertSearch search(segment_.get());
27	    auto invert_res = search.exec_invert_cond_tree(invert_cond_.get());
28	    if (!invert_res) {
29	      return Status::InternalError("Execute invert search failed: ",
30	                                   invert_res.error().message());
31	    }
32	    invert_result_ = invert_res.value();
33	    invert_filter_ = invert_result_->make_filter();
34	  }
35	
36	  if (forward_plan_) {
37	    auto forward_result = arrow::acero::DeclarationToTable(*forward_plan_);
38	    if (!forward_result.ok()) {
39	      return Status::InternalError("Execute filter bitmap failed: ",
40	                                   forward_result.status().ToString());
41	    }
42	    // has only one column with boolean type
43	    auto &forward_table = forward_result.ValueUnsafe();
44	    if (forward_table->num_columns() != 1 ||
45	        forward_table->column(0)->type() != arrow::boolean()) {
46	      return Status::InternalError("Filter bitmap is not boolean type");
47	    }
48	    forward_bitmap_ = forward_table->column(0);
49	  }
50	
51	  if (forward_filter_expr_) {
52	    // get schema to bind to Expression
53	    auto table = segment_->fetch(query_info_->get_forward_filter_field_names(),
54	                                 std::vector<int>{});
55	    if (!table) {
56	      return Status::InternalError("Fetch forward failed");
57	    }
58	    auto bind_res = forward_filter_expr_->Bind(*table->schema());
59	    if (!bind_res.ok()) {
60	      return Status::InternalError("Bind forward filter expression failed",
61	                                   bind_res.status().ToString());
62	    }
63	    *forward_filter_expr_ = bind_res.MoveValueUnsafe();
64	  }
65	  return Status::OK();
66	}
67	
68	bool DocFilter::empty() const {
69	  return !(delete_filter_ || invert_filter_ || forward_plan_ ||
70	           forward_filter_expr_);
71	}
72	
73	bool DocFilter::is_filtered(uint64_t id) const {
74	  if (delete_filter_ && delete_filter_->is_filtered(id)) {
75	    return true;
76	  }
77	  if (invert_filter_ && invert_filter_->is_filtered(id)) {
78	    return true;
79	  }
80	  auto forward_bit = get_forward_bit(id);
81	  if (!forward_bit) {
82	    return false;
83	  }
84	  // revert to return false if forward filter is matched
85	  return !forward_bit.value();
86	}
87	
88	std::optional<bool> DocFilter::get_forward_bit(uint64_t id) const {
89	  if (forward_filter_expr_) {
90	    return is_matched_by_forward_filter(id);
91	  }
92	  if (!forward_bitmap_) {
93	    return std::nullopt;
94	  }
95	  uint64_t rows_seen = 0;
96	  for (int c = 0; c < forward_bitmap_->num_chunks(); c++) {
97	    const auto &arr = forward_bitmap_->chunk(c);
98	    if (id < rows_seen + arr->length()) {
99	      auto *bool_array = static_cast<arrow::BooleanArray *>(arr.get());
100	      return (*bool_array)[id - rows_seen].value_or(false);
101	    }
102	    rows_seen += arr->length();
103	  }
104	  LOG_ERROR("ID is out or range: id[%zu] count[%zu]", (size_t)id,
105	            (size_t)rows_seen);
106	  return std::nullopt;
107	}
108	
109	std::optional<std::vector<uint64_t>> DocFilter::get_bf_by_keys_and_update(
110	    float ratio) {
111	  auto meta = segment_->meta();
112	  if (!meta) {
113	    return std::nullopt;
114	  }
115	  // TODO: support forward
116	  if (!invert_result_) {
117	    return std::nullopt;
118	  }
119	  size_t doc_count = meta->doc_count();
120	  uint64_t bf_by_keys_threshold = static_cast<uint64_t>(doc_count * ratio);
121	
122	  // decide to use brute force by keys or not
123	  if (size_t match_count = invert_result_->count();
124	      match_count <= bf_by_keys_threshold) {
125	    std::vector<uint32_t> ids;
126	    invert_result_->extract_ids(&ids);
127	    invert_filter_.reset();
128	    invert_result_.reset();
129	    LOG_INFO(
130	        "Use brute force by keys, doc_count[%zu] invert_result_count[%zu] "
131	        "ratio[%.4f]",
132	        doc_count, match_count, ratio);
133	    return std::vector<uint64_t>(ids.begin(), ids.end());
134	  } else {
135	    LOG_DEBUG(
136	        "Not use brute force by keys, doc_count[%zu] invert_result_count[%zu] "
137	        "ratio[%.4f]",
138	        doc_count, match_count, ratio);
139	  }
140	  return std::nullopt;
141	}
142	
143	std::optional<bool> DocFilter::is_matched_by_forward_filter(uint64_t id) const {
144	  auto exec_batch =
145	      segment_->fetch(query_info_->get_forward_filter_field_names(), id);
146	  if (!exec_batch) {
147	    LOG_ERROR("Fetch forward failed, id[%zu]", (size_t)id);
148	    return std::nullopt;
149	  }
150	  auto maybe_result = arrow::compute::ExecuteScalarExpression(
151	      *forward_filter_expr_, *exec_batch);
152	  if (!maybe_result.ok()) {
153	    LOG_ERROR("Execute scalar expression failed, id[%zu] err[%s]", (size_t)id,
154	              maybe_result.status().ToString().c_str());
155	    return std::nullopt;
156	  }
157	  arrow::Datum datum = maybe_result.MoveValueUnsafe();
158	  if (datum.is_scalar()) {
159	    const auto &scalar = datum.scalar_as<arrow::BooleanScalar>();
160	    return scalar.is_valid && scalar.value;
161	  }
162	  LOG_ERROR("Datum is not scalar, id[%zu] type[%s]", (size_t)id,
163	            datum.type()->ToString().c_str());
164	  return std::nullopt;
165	}
166	
167	
168	}  // namespace zvec::sqlengine

